use soroban_sdk::{contract, contractimpl, contracttype, Address, Env};

#[contracttype]
pub enum DataKey {
    Admin,
    Balance(Address),
}

#[contract]
pub struct Token;

#[contractimpl]
impl Token {
    // Writes persistent storage and instance storage, and never asks who is calling.
    // Any account can invoke this for any address it likes.
    pub fn mint(env: Env, to: Address, amount: i128) {
        env.storage()
            .persistent()
            .set(&DataKey::Balance(to.clone()), &amount);
        env.storage().instance().set(&DataKey::Admin, &to);
    }
}

