use soroban_sdk::{contract, contractimpl, contracttype, Address, Env};

#[contracttype]
pub enum DataKey {
    Admin,
    Balance(Address),
}

#[contract]
pub struct Token;

#[contractimpl]
impl Token {
    // Authorized before the effect, so the caller has to have signed for `admin`.
    pub fn mint(env: Env, admin: Address, to: Address, amount: i128) {
        admin.require_auth();
        env.storage()
            .persistent()
            .set(&DataKey::Balance(to.clone()), &amount);
    }

    // A view function changes nothing, so it needs no authorization even though it
    // takes an address.
    pub fn balance(env: Env, who: Address) -> i128 {
        env.storage()
            .persistent()
            .get(&DataKey::Balance(who))
            .unwrap_or(0)
    }

    // A constructor has no caller to authorize: it runs at deploy time.
    pub fn __constructor(env: Env, admin: Address) {
        env.storage().instance().set(&DataKey::Admin, &admin);
    }
}

#[contractimpl]
impl Token {
    // The authorization lives in a helper in this file, which is one level of
    // delegation the analyser follows.
    pub fn burn(env: Env, from: Address, amount: i128) {
        Self::authorize(from.clone());
        env.storage()
            .persistent()
            .set(&DataKey::Balance(from), &amount);
    }

    fn authorize(from: Address) {
        from.require_auth();
    }
}
